package tn.hydra.common.id;

import org.hibernate.annotations.IdGeneratorType;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Marks a UUID identifier field as generated by {@link AssignedUuidGenerator}, which keeps a
 * pre-assigned id (only generating a random UUID when the id is null).
 *
 * <p>This is the modern, non-deprecated replacement for applying {@code @GenericGenerator},
 * mirroring how {@code @UuidGenerator} itself is meta-annotated with {@code @IdGeneratorType}.</p>
 */
@Target({ElementType.METHOD, ElementType.FIELD})
@Retention(RetentionPolicy.RUNTIME)
@IdGeneratorType(AssignedUuidGenerator.class)
public @interface AssignedUuid {
}